#!/usr/bin/env python3
"""Meridian Credits local JSON CLI."""
import json
import sys

CAP_CENTS = 2400
CURRENT_RELEASE = "1.0"


def assign_credits_1_0(lines):
    """Release 1.0 credits for one statement's complete charge set: 10% of
    each charge rounded down to integer cents, with CAP_CENTS shared by all
    lines of one account_id across its subscriptions. Within a cap group,
    credit goes to lines by earliest service_on, then increasing line_id."""
    assigned = {}
    remaining = {}
    for line in sorted(lines, key=lambda l: (l["service_on"], l["line_id"])):
        left = remaining.setdefault(line["account_id"], CAP_CENTS)
        credit = min(line["charge_cents"] // 10, left)
        assigned[line["line_id"]] = credit
        remaining[line["account_id"]] = left - credit
    return assigned


def quote_1_0(line):
    credit = assign_credits_1_0([line])[line["line_id"]]
    return {
        "release": "1.0",
        "line_id": line["line_id"],
        "credit_cents": credit,
        "amount_due_cents": line["charge_cents"] - credit,
    }


RELEASES = {"1.0": quote_1_0}


def handle(request):
    command = request.get("command")
    if command == "ping":
        return {"status": "ok", "product": "Meridian Credits"}
    if command == "quote":
        release = request.get("release", CURRENT_RELEASE)
        if release not in RELEASES:
            return {"error": "unsupported_release"}
        return RELEASES[release](request["line"])
    return {"error": "unknown_command"}


if __name__ == "__main__":
    json.dump(handle(json.load(sys.stdin)), sys.stdout)
    sys.stdout.write("\n")

import json
from pathlib import Path
import subprocess
import sys
import unittest

ROOT = Path(__file__).resolve().parents[1]

LINE = {
    "line_id": "L-1",
    "account_id": "A",
    "subscription_id": "S",
    "service_on": "2026-04-15",
    "charge_cents": 19999,
}


class QuoteTests(unittest.TestCase):
    def run_cli(self, request):
        got = subprocess.run([sys.executable, str(ROOT / "main.py")],
                             input=json.dumps(request), text=True, capture_output=True, check=True)
        return json.loads(got.stdout)

    def check_quote(self, line, release=None):
        request = {"command": "quote", "line": line}
        if release is not None:
            request["release"] = release
        return self.run_cli(request)

    def test_explicit_release(self):
        got = self.check_quote(LINE, release="1.0")
        self.assertEqual(got, {"release": "1.0", "line_id": "L-1",
                               "credit_cents": 1999, "amount_due_cents": 18000})

    def test_omitted_release_selects_current(self):
        got = self.check_quote(LINE)
        self.assertEqual(got, {"release": "1.0", "line_id": "L-1",
                               "credit_cents": 1999, "amount_due_cents": 18000})

    def test_credit_rounded_down(self):
        got = self.check_quote({**LINE, "line_id": "L-2", "charge_cents": 19999})
        self.assertEqual(got["credit_cents"], 1999)

    def test_cap_limits_single_line(self):
        got = self.check_quote({**LINE, "line_id": "L-3", "charge_cents": 30000})
        self.assertEqual(got, {"release": "1.0", "line_id": "L-3",
                               "credit_cents": 2400, "amount_due_cents": 27600})

    def test_credit_at_exact_cap(self):
        got = self.check_quote({**LINE, "line_id": "L-4", "charge_cents": 24000})
        self.assertEqual(got["credit_cents"], 2400)
        self.assertEqual(got["amount_due_cents"], 21600)

    def test_zero_charge(self):
        got = self.check_quote({**LINE, "line_id": "L-5", "charge_cents": 0})
        self.assertEqual(got, {"release": "1.0", "line_id": "L-5",
                               "credit_cents": 0, "amount_due_cents": 0})

